user_list = list(df['user']) if 'user' in df.columns else []
import re

pattern = r'\b(\w+)\s\1\b'
neg_repeats = 0
pos_repeats = 0

for target, text in zip(target_list, text_list):
    if re.search(pattern, text):
        if target == 0:
            neg_repeats += 1
        else:
            pos_repeats += 1

print(f"Tweets with repeated words – Negative: {neg_repeats}")
print(f"Tweets with repeated words – Positive: {pos_repeats}")
if neg_repeats > pos_repeats:
    print("Repeated-word tweets are more often negative.")
elif pos_repeats > neg_repeats:
    print("Repeated-word tweets are more often positive.")
else:
    print("No clear tendency.")
